insert into ee_private.templates(kind,definition) values ('estudo','{"name":"Estudo de Caso","title":"ANEXO II – ESTUDO DE CASO","pages":"56–59","owner":"Professor especializado, com participação da escola e da família","period":"annual","sections":[{"id":"identificacao","title":"I - Das informações Gerais do Estudante","fields":[{"id":"nome","label":"Nome do estudante","type":"text","options":[]},{"id":"nascimento","label":"Data de nascimento","type":"date","options":[]},{"id":"idade","label":"Idade","type":"text","options":[]},{"id":"escola","label":"Escola","type":"text","options":[]},{"id":"turma","label":"Ano/série e turma","type":"text","options":[]},{"id":"turno","label":"Turno","type":"text","options":[]},{"id":"endereco","label":"Endereço residencial","type":"text","options":[]},{"id":"responsaveis","label":"Responsáveis","type":"text","options":[]},{"id":"telefone","label":"Telefone","type":"text","options":[]},{"id":"emergencia","label":"Em caso de emergência, a quem contatar?","type":"text","options":[]},{"id":"contato_emergencia","label":"Telefone/WhatsApp","type":"text","options":[]},{"id":"elegibilidade","label":"Estudante elegível aos serviços da Educação Especial","type":"multiselect","options":["Deficiência Intelectual","Deficiência Visual","Deficiência Física","Deficiência Auditiva/Surdez","Surdocegueira","Deficiência Múltipla","Altas Habilidades/Superdotação","Transtorno do Espectro Autista - TEA","Outros"]},{"id":"outros","label":"Outros / observações sobre a elegibilidade","type":"text","options":[]}],"hint":"Registre a situação observada, inclusive se estiver em investigação. O formulário não exige diagnóstico clínico."},{"id":"apoio","title":"II - Identificação do Nível de Apoio","fields":[{"id":"nivel","label":"Nível de Apoio","type":"select","options":["Nível 1","Nível 2","Nível 3"]}],"hint":""},{"id":"estudante","title":"III - Informações Coletadas do/ sobre o Estudante","fields":[{"id":"relato","label":"Relato sobre o estudante","type":"textarea","options":[]}],"hint":"O estudante gosta da escola? Tem amigos ou colega predileto? Quais atividades prefere e quais são mais difíceis, e por quê? Solicita ajuda aos professores? O que pensa dos professores? Está satisfeito com os apoios disponíveis? Gostaria de outros apoios?"},{"id":"escola","title":"IV - Informações Coletadas da/ sobre a Escola","fields":[{"id":"relato","label":"Relato da escola","type":"textarea","options":[]}],"hint":"Participação nas atividades e espaços; interesses e expectativas percebidos pelos professores; desempenho, habilidades, potencialidades e desafios; envolvimento afetivo e social dos colegas; visão da comunidade escolar; barreiras comunicacionais, arquitetônicas, atitudinais e outras."},{"id":"familia","title":"V - Informações Coletadas da/ sobre a Família e/ou Responsáveis","fields":[{"id":"relato","label":"Relato da família e/ou responsáveis","type":"textarea","options":[]},{"id":"acompanhamentos","label":"Acompanhamentos clínicos ou terapêuticos: tipo, frequência, especialidade, profissional, contato, local, horário e dias da semana","type":"textarea","options":[]},{"id":"autoriza","label":"A escola pode contatar os profissionais que atendem o estudante?","type":"select","options":["SIM","NÃO"]},{"id":"especificar","label":"Especificar a autorização ou justificar a não autorização","type":"textarea","options":[]},{"id":"email_profissional","label":"E-mail(s) para contato","type":"text","options":[]}],"hint":"Opinião sobre a escola; participação e conhecimento dos direitos; habilidades e desafios; expectativas de escolarização e futuro profissional; reação à frustração, cansaço e mudanças de rotina; estratégias de autorregulação; necessidades de alimentação, higiene, comunicação ou interação. Para vários profissionais, descreva cada acompanhamento e sua autorização separadamente."},{"id":"especializado","title":"VI - Informações coletadas pelo Professor Especializado da Educação Especial durante o Estudo de Caso","fields":[{"id":"relato","label":"Observações do professor especializado","type":"textarea","options":[]}],"hint":"Etapa de alfabetização (pré-silábica, silábica, silábico-alfabética ou alfabética); nível de Libras/Braille, se aplicável; quatro operações; estereotipias e contexto; hiperfocos; comunicação e comunicação alternativa; motricidade fina e ampla; recursos acessíveis que beneficiam o estudante."},{"id":"assinaturas","title":"Assinaturas","fields":[{"id":"diretor","label":"Nome, Carimbo e Assinatura do Diretor Escolar/Diretor de Escola","type":"signature","options":[]},{"id":"coordenador","label":"Nome e Assinatura do Coordenador de Gestão Pedagógica","type":"signature","options":[]},{"id":"especializado","label":"Nome e Assinatura do Professor Especializado","type":"signature","options":[]}],"hint":"Informe os nomes. O PDF reserva espaço para assinatura e carimbo. Digitar o nome ou aprovar na plataforma não equivale a assinar o documento."}]}'::jsonb);
insert into ee_private.templates(kind,definition) values ('paee','{"name":"PAEE","title":"ANEXO III – PLANO DE ATENDIMENTO EDUCACIONAL ESPECIALIZADO / PAEE","pages":"65–67","owner":"Professor especializado, em articulação com os demais profissionais","period":"annual","sections":[{"id":"identificacao","title":"I - Dados pessoais e escolares","fields":[{"id":"nome","label":"Nome do estudante","type":"text","options":[]},{"id":"nascimento","label":"Data de Nascimento","type":"date","options":[]},{"id":"sexo","label":"Sexo","type":"select","options":["Feminino","Masculino"]},{"id":"escola","label":"Escola","type":"text","options":[]},{"id":"turno","label":"Turno","type":"text","options":[]},{"id":"turma","label":"Turma","type":"text","options":[]},{"id":"ano_escolar","label":"Ano de Escolaridade","type":"text","options":[]},{"id":"elegibilidade","label":"Estudante elegível aos serviços da Educação Especial","type":"multiselect","options":["Deficiência Intelectual","Deficiência Visual","Deficiência Física","Deficiência Auditiva/Surdez","Surdocegueira","Deficiência Múltipla","Altas Habilidades/Superdotação","Transtorno do Espectro Autista - TEA"]},{"id":"nivel","label":"Nível de Apoio","type":"select","options":["Nível 1","Nível 2","Nível 3"]},{"id":"observacoes","label":"Observações","type":"textarea","options":[]}],"hint":""},{"id":"sintese","title":"II - Informações identificadas no Estudo de Caso","fields":[{"id":"relato","label":"Fazer um breve relato do que foi observado no Estudo de Caso.","type":"textarea","options":[]}],"hint":""},{"id":"servicos","title":"III - Apoios, Recursos e Serviços","fields":[{"id":"servicos","label":"Serviços indicados a partir do Estudo de Caso","type":"multiselect","options":["Recursos Pedagógicos, de Acessibilidade e de Tecnologia Assistiva","Professor de Libras ou Professor interlocutor de Libras","Professor Instrutor-mediador ou Guia-intérprete","Serviço de Profissional de Apoio Escolar"]},{"id":"dimensoes","label":"Necessidades de apoio no cotidiano escolar","type":"multiselect","options":["Alimentação","Higiene pessoal, íntima e bucal, incluindo banheiro","Locomoção e autocuidado","Mediação das atividades, comunicação e interação social","Instrumentos para oportunizar a socialização"]},{"id":"motivos","label":"Descrever os motivos para indicação do Apoio:","type":"textarea","options":[]},{"id":"habilidades","label":"Descrever as habilidades que serão desenvolvidas durante o Atendimento Educacional Especializado - AEE de forma complementar ou suplementar ao currículo:","type":"textarea","options":[]},{"id":"estrategias","label":"Descrever quais estratégias serão utilizadas para desenvolvimento das habilidades descritas no Atendimento Educacional Especializado (Sala de Recursos ou Modalidade Itinerante):","type":"textarea","options":[]}],"hint":""},{"id":"planejamento","title":"Planejamento bimestral do Atendimento Educacional Especializado","fields":[{"id":"b1","label":"1º Bimestre","type":"textarea","options":[]},{"id":"b2","label":"2º Bimestre","type":"textarea","options":[]},{"id":"b3","label":"3º Bimestre","type":"textarea","options":[]},{"id":"b4","label":"4º Bimestre","type":"textarea","options":[]}],"hint":"Apresente as ações pedagógicas propostas para promover o desenvolvimento da aprendizagem do estudante."},{"id":"orientacoes","title":"Orientações aos profissionais","fields":[{"id":"regente","label":"Em relação ao Professor Regente de classes e turmas ou professor de componentes curriculares, registrar as informações necessárias, contribuindo com a atuação do Professor:","type":"textarea","options":[]},{"id":"colaborativo","label":"Em relação ao Projeto Ensino Colaborativo realizado no turno escolar, registrar as informações necessárias, contribuindo com a atuação do Professor Especializado atuante:","type":"textarea","options":[]},{"id":"equipe","label":"Em relação à equipe gestora e outros profissionais da Escola (Gerente de Organização Escolar - GOE, Profissional de Apoio Escolar, merendeira, entre outros), registrar as informações necessárias, contribuindo com a atuação dos profissionais:","type":"textarea","options":[]}],"hint":""},{"id":"recursos","title":"Materiais, acessibilidade e superação de barreiras","fields":[{"id":"materiais","label":"Descreva os materiais pedagógicos, recursos de acessibilidade e tecnologias assistivas que devem ser adaptados ou disponibilizados para garantir o acesso do estudante aos conteúdos curriculares.","type":"textarea","options":[]},{"id":"pdde","label":"Indicar materiais e equipamentos a serem adquiridos pela Escola, por meio dos recursos do PDDE-Paulista:","type":"textarea","options":[]},{"id":"barreiras","label":"Quais medidas a escola deve implementar para superar as barreiras identificadas no Estudo de Caso?","type":"textarea","options":[]}],"hint":""},{"id":"assinaturas","title":"Assinaturas","fields":[{"id":"diretor","label":"Nome, Carimbo e Assinatura do Diretor Escolar/Diretor de Escola","type":"signature","options":[]},{"id":"coordenador","label":"Nome e Assinatura do Coordenador de Gestão Pedagógica","type":"signature","options":[]},{"id":"especializado","label":"Nome e Assinatura do Professor Especializado","type":"signature","options":[]},{"id":"colaborativo","label":"Nome e Assinatura do Professor Especializado do Projeto Ensino Colaborativo","type":"signature","options":[]},{"id":"regentes","label":"Assinatura dos Professores Regentes de classes e turmas ou professores de componentes curriculares","type":"signature","options":[]},{"id":"responsavel","label":"Ciência e assinatura do responsável legal","type":"signature","options":[]}],"hint":"Informe os nomes. O PDF reserva espaço para assinatura e carimbo. Digitar o nome ou aprovar na plataforma não equivale a assinar o documento."}]}'::jsonb);
insert into ee_private.templates(kind,definition) values ('pei','{"name":"PEI","title":"ANEXO IV – PLANO EDUCACIONAL INDIVIDUALIZADO - PEI","pages":"79","owner":"Professor regente do componente curricular, com apoio do especializado","period":"subject","sections":[{"id":"identificacao","title":"Identificação","fields":[{"id":"nome","label":"Nome do estudante","type":"text","options":[]},{"id":"regente","label":"Nome do Professor Regente","type":"text","options":[]},{"id":"especializado","label":"Nome do Professor Especializado da Educação Especial","type":"text","options":[]},{"id":"componente","label":"Componente Curricular","type":"text","options":[]},{"id":"bimestre","label":"Período","type":"select","options":["1º Bimestre","2º Bimestre","3º Bimestre","4º Bimestre"]}],"hint":""},{"id":"curriculo","title":"Conteúdos e habilidades","fields":[{"id":"relato","label":"Quais conteúdos e habilidades do Currículo da Rede Estadual Paulista serão desenvolvidos no bimestre?","type":"textarea","options":[]}],"hint":""},{"id":"estrategias","title":"Estratégias e acessibilidade","fields":[{"id":"relato","label":"Quais estratégias, intervenções pedagógicas e recursos de acessibilidade serão utilizados para favorecer o acesso, a participação e a aprendizagem do estudante?","type":"textarea","options":[]}],"hint":""},{"id":"avaliacao","title":"Acompanhamento da aprendizagem","fields":[{"id":"relato","label":"Quais instrumentos serão utilizados para acompanhar o aprendizado do estudante de forma inclusiva e individualizada?","type":"textarea","options":[]}],"hint":""},{"id":"atividades","title":"Atividades complementares","fields":[{"id":"relato","label":"Quais vídeos, livros, jogos, exercícios ou outras atividades podem ser indicados para apoiar, complementar, suplementar e fortalecer o aprendizado do estudante neste componente curricular, considerando suas potencialidades, especificidades e ritmo de aprendizagem?","type":"textarea","options":[]}],"hint":""},{"id":"assinaturas","title":"Assinaturas","fields":[{"id":"diretor","label":"Nome, Carimbo e Assinatura do Diretor Escolar/Diretor de Escola","type":"signature","options":[]},{"id":"coordenador","label":"Nome e Assinatura do Coordenador de Gestão Pedagógica","type":"signature","options":[]},{"id":"especializado","label":"Nome e Assinatura do Professor Especializado","type":"signature","options":[]},{"id":"colaborativo","label":"Nome e Assinatura do Professor Especializado do Projeto Ensino Colaborativo","type":"signature","options":[]},{"id":"regentes","label":"Assinatura dos Professores Regentes de classes e turmas ou professores de componentes curriculares","type":"signature","options":[]}],"hint":"Informe os nomes. O PDF reserva espaço para assinatura e carimbo. Digitar o nome ou aprovar na plataforma não equivale a assinar o documento."}]}'::jsonb);
insert into ee_private.templates(kind,definition) values ('acolhimento','{"name":"Acolhimento da família","title":"ANEXO V – RELATÓRIO DE ACOLHIMENTO, ORIENTAÇÃO E RETORNO BIMESTRAL AOS PAIS OU RESPONSÁVEIS SOBRE O PLANO DE ATENDIMENTO EDUCACIONAL ESPECIALIZADO - PAEE","pages":"90","owner":"Professores especializado e regentes, com coordenação pedagógica","period":"annual","sections":[{"id":"identificacao","title":"Identificação","fields":[{"id":"escola","label":"Escola","type":"text","options":[]},{"id":"nome","label":"Aluno(a)","type":"text","options":[]},{"id":"turma","label":"Série/Ano","type":"text","options":[]},{"id":"data_inicial","label":"Data do acolhimento/orientação inicial","type":"date","options":[]},{"id":"data_retorno","label":"Data do retorno bimestral","type":"date","options":[]}],"hint":""},{"id":"acolhimento","title":"I. Eixos norteadores para Acolhimento e Orientação Inicial","fields":[{"id":"estudo","label":"Apresentar o relatório final do Estudo de Caso;","type":"textarea","options":[]},{"id":"apoios","label":"Apresentar quais apoios, recursos e serviços serão disponibilizados ao estudante;","type":"textarea","options":[]},{"id":"metas","label":"Apresentar os objetivos e Metas do Plano de Atendimento Educacional Especializado - PAEE;","type":"textarea","options":[]},{"id":"frequencia","label":"Explicar sobre como se dará a frequência e organização do atendimento;","type":"textarea","options":[]},{"id":"casa","label":"Orientações de como a família poderá apoiar em casa","type":"textarea","options":[]}],"hint":""},{"id":"assinaturas","title":"Assinaturas","fields":[{"id":"diretor","label":"Nome, Carimbo e Assinatura do Diretor Escolar/Diretor de Escola","type":"signature","options":[]},{"id":"coordenador","label":"Nome e Assinatura do Coordenador de Gestão Pedagógica","type":"signature","options":[]},{"id":"especializado","label":"Nome e Assinatura do Professor Especializado","type":"signature","options":[]},{"id":"regentes","label":"Assinatura 