insert into ee_private.templates(kind,definition) values ('retorno','{"name":"Retorno bimestral à família","title":"ANEXO V – ALINHAMENTO BIMESTRAL COM A FAMÍLIA","pages":"91–92","owner":"Professores especializado e regentes, com coordenação pedagógica","period":"term","sections":[{"id":"identificacao","title":"Identificação","fields":[{"id":"escola","label":"Escola","type":"text","options":[]},{"id":"nome","label":"Aluno(a)","type":"text","options":[]},{"id":"turma","label":"Série/Ano","type":"text","options":[]},{"id":"data","label":"Data","type":"date","options":[]}],"hint":""},{"id":"objetivos","title":"Objetivos de aprendizagem","fields":[{"id":"relato","label":"Quais objetivos de aprendizagem foram definidos para o estudante neste período?","type":"textarea","options":[]}],"hint":""},{"id":"metodos","title":"Metodologias e recursos","fields":[{"id":"relato","label":"Quais metodologias, recursos e abordagens foram aplicados para favorecer o desenvolvimento do estudante?","type":"textarea","options":[]}],"hint":""},{"id":"progressos","title":"Progressos no bimestre","fields":[{"id":"relato","label":"Quais progressos foram identificados no desempenho acadêmico, na participação ou nas habilidades do estudante ao longo do bimestre?","type":"textarea","options":[]}],"hint":""},{"id":"desafios","title":"Desafios e fatores envolvidos","fields":[{"id":"relato","label":"Quais desafios foram enfrentados pelo estudante durante o bimestre? Há fatores que impactaram seu processo de aprendizagem?","type":"textarea","options":[]}],"hint":""},{"id":"intervencoes","title":"Próximas intervenções","fields":[{"id":"relato","label":"Quais intervenções, adaptações ou apoios serão implementados para enfrentar os desafios identificados e promover avanços?","type":"textarea","options":[]}],"hint":""},{"id":"assinaturas","title":"Assinaturas","fields":[{"id":"diretor","label":"Nome, Carimbo e Assinatura do Diretor Escolar/Diretor de Escola","type":"signature","options":[]},{"id":"coordenador","label":"Nome e Assinatura do Coordenador de Gestão Pedagógica","type":"signature","options":[]},{"id":"especializado","label":"Nome e Assinatura do Professor Especializado","type":"signature","options":[]},{"id":"regentes","label":"Assinatura dos Professores Regentes de classes e turmas ou professores de componentes curriculares","type":"signature","options":[]},{"id":"responsavel","label":"Ciência e assinatura do responsável legal","type":"signature","options":[]}],"hint":"Informe os nomes. O PDF reserva espaço para assinatura e carimbo. Digitar o nome ou aprovar na plataforma não equivale a assinar o documento."}]}'::jsonb);
